sys_script_include.script:
var InsuranceUtils = Class.create();
InsuranceUtils.prototype = {
    initialize: function() {
    },
     getAllPoliciesByPatient: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_insurance');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_policy_num') + ';' + gr.getValue('u_provider') + ';' + gr.getValue('u_coverage') + '\n';
        }
        return result || false;
    },

    // 2. Get active policies (u_status = 'Active')
    getActivePolicies: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_insurance');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.addQuery('u_status', 'Active');
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_policy_num') + ';' + gr.getValue('u_provider') + '\n';
        }
        return result || false;
    },

    // 3. Get policy by number
    getPolicyByNumber: function (policyNumber) {
        var gr = new GlideRecord('u_insurance');
        gr.addQuery('u_policy_num', policyNumber);
        gr.query();
        if (gr.next()) {
            return gr.getValue('u_policy_num') + ';' + gr.getValue('u_provider') + ';' + gr.getValue('u_coverage');
        }
        return false;
    },

    // 4. Get insurance provider(s) for patient
    getProvidersByPatient: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_insurance');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_provider') + '\n';
        }
        return result || false;
    },

    // 5. Get coverage details by policy number
    getCoverageDetails: function (policyNumber) {
        var gr = new GlideRecord('u_insurance');
        gr.addQuery('u_policy_num', policyNumber);
        gr.query();
        if (gr.next()) {
            return gr.getValue('u_coverage');
        }
        return false;
    },

    type: 'InsuranceUtils'
};
